const readline=require('node:readline');
readline.createInterface({input:process.stdin}).on('line',line=>{const r=JSON.parse(line);if(r.id===undefined)return;const send=result=>process.stdout.write(JSON.stringify({jsonrpc:'2.0',id:r.id,result})+'\n');if(r.method==='initialize')send({protocolVersion:'2025-03-26',capabilities:{tools:{}},serverInfo:{name:'test',version:'1'}});else if(r.method==='tools/list')send({tools:[{name:'echo',description:'Echo test input',inputSchema:{type:'object',properties:{text:{type:'string'}},required:['text']}}]});else if(r.method==='tools/call'){if(r.params.arguments.text==='wait')return;send({content:[{type:'text',text:r.params.arguments.text}]});}else process.stdout.write(JSON.stringify({jsonrpc:'2.0',id:r.id,error:{code:-32601,message:'Unknown'}})+'\n');});
